// Agrupa las filas por SEDE y arma los parametros de la plantilla.
//
// IMPORTANTE: los parametros de una plantilla de WhatsApp NO pueden contener
// saltos de linea, tabulaciones ni 4 espacios seguidos (error 132000 de Meta).
// Por eso el salto de linea vive en la plantilla aprobada y aqui solo van
// valores cortos de una linea.

const ETIQUETAS = {
  ARRIENDO: 'arriendo',
  SERVICIOS: 'servicios',
  NOMINA: 'nomina',
  TRANSPORTE: 'transporte',
  MERCANCIA: 'mercancia',
  OTROS: 'otros gastos',
  VENTAS: 'ventas',
};

const dinero = (valor) => '$' + Math.round(valor).toLocaleString('es-CO');

const sedes = new Map();

for (const { json } of $input.all()) {
  if (!json.destinatario) continue; // fila vacia de alwaysOutputData

  const id = json.sede_id;
  if (!sedes.has(id)) {
    sedes.set(id, {
      sedeId: id,
      sede: String(json.sede),
      negocio: String(json.negocio),
      // Un BSUID (CO.1710...) va tal cual; un telefono se limpia a digitos.
      destinatario: String(json.destinatario).includes('.')
        ? String(json.destinatario)
        : String(json.destinatario).replace(/\D/g, ''),
      contacto: String(json.contacto || '').split(' ')[0] || 'Hola',
      desde: json.desde,
      hasta: json.hasta,
      ingresos: 0,
      gastos: 0,
      movimientos: 0,
      categoriasGasto: [],
    });
  }

  const acumulado = sedes.get(id);
  const total = Number(json.total) || 0;
  acumulado.movimientos += Number(json.movimientos) || 0;

  if (json.tipo === 'ingreso') {
    acumulado.ingresos += total;
  } else {
    acumulado.gastos += total;
    acumulado.categoriasGasto.push({ categoria: json.categoria, total });
  }
}

console.log(`[Resumen semanal] Sedes con movimientos: ${sedes.size}`);

return [...sedes.values()].map((s) => {
  const balance = s.ingresos - s.gastos;
  const mayor = s.categoriasGasto.sort((a, b) => b.total - a.total)[0];

  // Sin codigo de pais el envio se acepta y nunca llega: mejor verlo aqui.
  if (!s.destinatario.includes('.') && s.destinatario.length < 11) {
    console.error(
      `[AVISO] La sede "${s.sede}" tiene el telefono sin codigo de pais: ${s.destinatario}. Corregir en Sede.telefono.`,
    );
  }

  console.log(
    `[Resumen semanal] ${s.negocio} / ${s.sede}: ingresos ${s.ingresos}, gastos ${s.gastos}, ${s.movimientos} movimientos`,
  );

  return {
    json: {
      ...s,
      // Parametros de la plantilla (una linea cada uno).
      // Se nombra la sede porque un duenno puede tener varias, cada una con su
      // linea de WhatsApp, y si no no sabria a cual corresponde el resumen.
      p1_contacto: s.contacto,
      p2_negocio: `${s.negocio} (${s.sede})`,
      p3_ingresos: dinero(s.ingresos),
      p4_gastos: dinero(s.gastos),
      p5_balance: (balance >= 0 ? '+' : '-') + dinero(Math.abs(balance)),
      p6_mayorGasto: mayor
        ? `${ETIQUETAS[mayor.categoria] || mayor.categoria} (${dinero(mayor.total)})`
        : 'sin gastos registrados',
    },
  };
});

for (const item of $input.all()) {
  console.error('[Resumen semanal] ERROR de envío:', JSON.stringify(item.json).slice(0, 800));
}
return $input.all();
